import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, Color } from 'three/webgpu';
import { uv, mix, vec3, time } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Array<Object>} [textContent]
 * @property {Array<Object>} [cinematicPrimitives]
 * @property {Object} [visualSpec]
 * @property {Object} [intent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {any} textureLoader
 * @property {any} glbLoader
 * @property {any} videoLoader
 * @property {any} fontAtlas
 * @property {any} primitives
 * @property {Function} emit
 * @property {string} tier
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, Color } = ctx.THREE;

  const root = new Group();

  // ---------- BACKDROP ----------
  const backdropGeo = new PlaneGeometry(7, 6);
  const gradientStops = config.visualSpec?.gradientStops || [
    { at: 0, hex: '#0b0b10' },
    { at: 1, hex: '#14141a' },
  ];
  const colorA = new Color(gradientStops[0].hex);
  const colorB = new Color(gradientStops[gradientStops.length - 1].hex);

  // Node material using vertical gradient
  const backdropMat = new MeshStandardNodeMaterial();
  backdropMat.colorNode = mix(
    vec3(colorA.r, colorA.g, colorA.b),
    vec3(colorB.r, colorB.g, colorB.b),
    uv().y
  );
  backdropMat.ness = 0.7;
  backdropMat.metalness = 0.0;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------- PLATES ----------
  const plateCount = 6;
  const plateWidth = 1.9;
  const plateHeight = 1.2;
  const platePitch = 1.5;
  const columnX = 0.9;

  // Load texture once (same for all plates as per spec)
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  const plateMaterial = new MeshStandardNodeMaterial();
  plateMaterial.roughness = 0.6;
  plateMaterial.metalness = 0.1;
  plateMaterial.clearcoat = 0.1;

  texturePromise.then((tex) => {
    plateMaterial.map = tex;
    plateMaterial.needsUpdate = true;
  });

  const plates = [];

  for (let i = 0; i < plateCount; i++) {
    const geo = new PlaneGeometry(plateWidth, plateHeight);
    const mesh = new Mesh(geo, plateMaterial);
    mesh.position.set(columnX, (i - (plateCount - 1) / 2) * platePitch, 0);
    root.add(mesh);
    plates.push(mesh);
  }

  // ---------- BEVEL FRAME ----------
  const bevelThickness = 0.03;
  const bevelGeo = new PlaneGeometry(plateWidth + bevelThickness * 2, plateHeight + bevelThickness * 2);
  const bevelMat = new MeshStandardNodeMaterial();
  bevelMat.color = new Color('#16161d'); // ink
  bevelMat.roughness = 0.5;
  bevelMat.metalness = 0.5;
  bevelMat.clearcoat = 0.1;

  plates.forEach((plate) => {
    const frame = new Mesh(bevelGeo, bevelMat);
    frame.position.copy(plate.position);
    root.add(frame);
  });

  // ---------- ACCENT STRIP ----------
  const accentWidth = 0.03;
  const accentGeo = new PlaneGeometry(accentWidth, plateHeight);
  const accentMat = new MeshStandardNodeMaterial();
  accentMat.color = new Color('#ff2a38');
  accentMat.emissive = new Color('#ff2a38');
  accentMat.emissiveIntensity = 1.4;
  accentMat.roughness = 0.5;
  accentMat.metalness = 0.0;
  const accentStrip = new Mesh(accentGeo, accentMat);
  // Position at left edge of the plate nearest y=0 (index centered)
  const centerPlate = plates[Math.floor(plateCount / 2)];
  accentStrip.position.set(
    centerPlate.position.x - plateWidth / 2 - accentWidth / 2,
    centerPlate.position.y,
    centerPlate.position.z + 0.01
  );
  root.add(accentStrip);

  // ---------- TEXT ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  items.forEach((item) => {
    const opts = {
      fontSize: item.typography?.fontSize ?? 18,
      color: config.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'left',
    };
    const txtObj = ctx.fontAtlas.createText(item.text, opts);
    // Position logic: headline pinned, captions near plates
    if (item.role === 'headline') {
      txtObj.position.set(-1.6, 1.9, 0);
    } else {
      // Find matching plate by index order
      const idx = items.indexOf(item) - 1; // first caption after headline
      if (idx >= 0 && idx < plates.length) {
        const p = plates[idx];
        txtObj.position.set(-1.6, p.position.y, 0);
      } else {
        txtObj.position.set(0, 0, 0);
      }
    }
    root.add(txtObj);
  });

  // ---------- CINEMATIC PRIMITIVES ----------
  const primitiveInstances = [];

  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((prim) => {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(root, prim.params || {});
        primitiveInstances.push(instance);
      }
    });
  }

  // ---------- USERDATA ----------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose materials and geometry
    backdropMat.dispose();
    backdropGeo.dispose();

    plateMaterial.dispose();
    plates.forEach((p) => p.geometry.dispose());

    bevelMat.dispose();
    // bevel geometry reused per plate, dispose once
    bevelGeo.dispose();

    accentMat.dispose();
    accentGeo.dispose();

    // Cleanup primitives
    primitiveInstances.forEach((inst) => {
      if (inst && typeof inst.cleanup === 'function') inst.cleanup();
    });

    // Kill any GSAP timelines (none created here but safe)
    gsap.globalTimeline.clear();
  };

  return root;
}
